insert into public.landmarks (id, name, lat, lng, neighborhood, year, summary, station_id, freedom_trail) values
  ('state-house', 'Massachusetts State House', 42.3587, -71.0638, 'Beacon Hill', '1798', 'Designed by Charles Bulfinch and completed in 1798 on land once owned by John Hancock, the State House is the seat of Massachusetts government. Its dome was first wooden, then sheathed in copper by Paul Revere''s company in 1802, and gilded with gold leaf in 1874.', 'place-pktrm', true),
  ('park-street-church', 'Park Street Church', 42.3568, -71.0621, 'Downtown', '1809', 'Founded in 1809, Park Street Church stands at the corner of Park and Tremont streets, a spot nicknamed Brimstone Corner. William Lloyd Garrison gave a major anti-slavery address here in 1829, and the hymn "America" (My Country, ''Tis of Thee) was first sung publicly on its steps in 1831.', 'place-pktrm', true),
  ('granary', 'Granary Burying Ground', 42.3573, -71.0615, 'Downtown', '1660', 'Established in 1660, the Granary Burying Ground is the resting place of Paul Revere, Samuel Adams, John Hancock, and the victims of the Boston Massacre. It takes its name from a grain storehouse that once stood next door.', 'place-pktrm', true),
  ('kings-chapel', 'King''s Chapel', 42.3581, -71.06, 'Downtown', '1754', 'King''s Chapel was founded in 1686 as the first Anglican church in New England. The present stone building, designed by Peter Harrison, was completed in 1754; its planned steeple was never built, leaving the distinctive flat-topped tower.', 'place-gover', true),
  ('old-south', 'Old South Meeting House', 42.357, -71.0586, 'Downtown', '1729', 'Built in 1729 as a Puritan meeting house, Old South was the largest building in colonial Boston. On December 16, 1773, some 5,000 colonists gathered here in the meeting that led directly to the Boston Tea Party.', 'place-dwnxg', true),
  ('old-state-house', 'Old State House', 42.3588, -71.0575, 'Downtown', '1713', 'Built in 1713, the Old State House is Boston''s oldest surviving public building and was the seat of colonial government. The Boston Massacre took place outside it in 1770, and the Declaration of Independence was first read to Bostonians from its east balcony on July 18, 1776.', 'place-state', true),
  ('faneuil-hall', 'Faneuil Hall', 42.36, -71.0562, 'Downtown', '1742', 'A gift to the town from merchant Peter Faneuil, Faneuil Hall opened in 1742 as a market and meeting hall. Speeches by Samuel Adams and others urging independence earned it the name "the Cradle of Liberty". Its grasshopper weathervane dates to 1742.', 'place-state', true),
  ('paul-revere-house', 'Paul Revere House', 42.3637, -71.0537, 'North End', 'c. 1680', 'Built around 1680, this is the oldest surviving house in downtown Boston. Paul Revere owned it from 1770 to 1800 and left from here on his midnight ride of April 18, 1775. It has operated as a museum since 1908.', 'place-haecl', true),
  ('old-north-church', 'Old North Church', 42.3663, -71.0544, 'North End', '1723', 'Built in 1723, Old North is Boston''s oldest standing church building. On the night of April 18, 1775, two lanterns hung in its steeple signalled that British troops were crossing the Charles by water: "one if by land, two if by sea".', 'place-haecl', true),
  ('uss-constitution', 'USS Constitution', 42.3724, -71.0566, 'Charlestown', '1797', 'Launched in Boston in 1797, USS Constitution is the world''s oldest commissioned warship still afloat. She earned the nickname "Old Ironsides" in the War of 1812 when British cannonballs appeared to bounce off her oak hull.', 'place-north', true),
  ('bunker-hill', 'Bunker Hill Monument', 42.3764, -71.0608, 'Charlestown', '1843', 'This 221-foot granite obelisk, completed in 1843, commemorates the Battle of Bunker Hill of June 17, 1775, the first major battle of the Revolutionary War. It actually stands on Breed''s Hill, where most of the fighting took place.', 'place-ccmnl', true),
  ('bpl', 'Boston Public Library', 42.3493, -71.0782, 'Back Bay', '1895', 'The Boston Public Library was the first large free municipal library in the United States. Its McKim Building on Copley Square, designed by Charles Follen McKim and opened in 1895, was conceived as a "palace for the people" and carries the inscription "Free to All".', 'place-coecl', false),
  ('trinity-church', 'Trinity Church', 42.35, -71.0755, 'Back Bay', '1877', 'Designed by Henry Hobson Richardson and consecrated in 1877, Trinity Church defined the style now called Richardsonian Romanesque. It rests on thousands of wooden piles driven into Back Bay''s filled land and is famously reflected in the glass of the neighbouring Hancock tower.', 'place-coecl', false),
  ('public-garden', 'Boston Public Garden', 42.3541, -71.07, 'Back Bay', '1837', 'Established in 1837, the Public Garden was the first public botanical garden in the United States. Its Swan Boats have paddled the lagoon since 1877, and its small suspension footbridge and equestrian statue of George Washington are city icons.', 'place-armnl', false),
  ('fenway-park', 'Fenway Park', 42.3467, -71.0972, 'Fenway–Kenmore', '1912', 'Open since 1912, Fenway Park is the oldest ballpark in Major League Baseball and home of the Boston Red Sox. Its 37-foot left-field wall, the Green Monster, and its hand-operated scoreboard are among the most recognisable features in sport.', 'place-kencl', false),
  ('mit-dome', 'MIT Great Dome', 42.3601, -71.0921, 'Cambridge', '1916', 'The Great Dome crowns Building 10 at the heart of MIT''s Cambridge campus, designed by William Welles Bosworth and opened in 1916 when the Institute moved across the Charles from Boston. Modelled on the Pantheon, it overlooks Killian Court and is a favourite target of student "hacks".', 'place-knncl', false),
  ('john-harvard', 'John Harvard Statue', 42.3745, -71.1172, 'Cambridge', '1884', 'Daniel Chester French''s 1884 bronze in Harvard Yard is nicknamed the "Statue of Three Lies": its inscription calls John Harvard the founder (he was a benefactor), dates the college to 1638 (it was 1636), and the face is a student model''s, since no likeness of Harvard survives. Visitors rub its left shoe for luck.', 'place-harsq', false),
  ('longfellow-bridge', 'Longfellow Bridge', 42.3617, -71.0756, 'Charles River', '1906', 'Opened in 1906 and later renamed for poet Henry Wadsworth Longfellow, this steel-arch bridge carries the Red Line and road traffic over the Charles River between Boston and Cambridge. Its four granite towers earned it the nickname "Salt-and-Pepper Bridge".', 'place-chmnl', false),
  ('zakim-bridge', 'Zakim Bridge', 42.3688, -71.0631, 'West End', '2003', 'Completed in 2003 as the centrepiece of the Big Dig, the Leonard P. Zakim Bunker Hill Memorial Bridge carries Interstate 93 over the Charles River. Its two inverted-Y towers deliberately echo the Bunker Hill Monument nearby.', 'place-north', false),
  ('custom-house', 'Custom House Tower', 42.3591, -71.0535, 'Waterfront', '1915', 'The Greek Revival Custom House was completed in 1847 at what was then the water''s edge. The 496-foot tower added in 1915 made it Boston''s tallest building for nearly half a century, exempt from city height limits because it was federal property.', 'place-aqucl', false)
