insert into public.game_locations (id, kind, name, aliases, lat, lng, difficulty, station_id, summary) values
  ('state-house', 'landmark', 'Massachusetts State House', array['state house', 'massachusetts state house', 'boston state house', 'the state house', 'new state house']::text[], 42.3587, -71.0638, 1, 'place-pktrm', 'Designed by Charles Bulfinch and completed in 1798 on land once owned by John Hancock, the State House is the seat of Massachusetts government. Its dome was first wooden, then sheathed in copper by Paul Revere''s company in 1802, and gilded with gold leaf in 1874.'),
  ('park-street-church', 'landmark', 'Park Street Church', array['park street church', 'park st church', 'brimstone corner']::text[], 42.3568, -71.0621, 2, 'place-pktrm', 'Founded in 1809, Park Street Church stands at the corner of Park and Tremont streets, a spot nicknamed Brimstone Corner. William Lloyd Garrison gave a major anti-slavery address here in 1829, and the hymn "America" (My Country, ''Tis of Thee) was first sung publicly on its steps in 1831.'),
  ('granary', 'landmark', 'Granary Burying Ground', array['granary burying ground', 'granary burial ground', 'granary cemetery', 'old granary burying ground', 'the granary']::text[], 42.3573, -71.0615, 2, 'place-pktrm', 'Established in 1660, the Granary Burying Ground is the resting place of Paul Revere, Samuel Adams, John Hancock, and the victims of the Boston Massacre. It takes its name from a grain storehouse that once stood next door.'),
  ('kings-chapel', 'landmark', 'King''s Chapel', array['kings chapel', 'king s chapel', 'kings chapel boston']::text[], 42.3581, -71.06, 3, 'place-gover', 'King''s Chapel was founded in 1686 as the first Anglican church in New England. The present stone building, designed by Peter Harrison, was completed in 1754; its planned steeple was never built, leaving the distinctive flat-topped tower.'),
  ('old-south', 'landmark', 'Old South Meeting House', array['old south meeting house', 'old south meetinghouse', 'old south', 'old south church meeting house']::text[], 42.357, -71.0586, 2, 'place-dwnxg', 'Built in 1729 as a Puritan meeting house, Old South was the largest building in colonial Boston. On December 16, 1773, some 5,000 colonists gathered here in the meeting that led directly to the Boston Tea Party.'),
  ('old-state-house', 'landmark', 'Old State House', array['old state house', 'old statehouse', 'old state house boston', 'towne house']::text[], 42.3588, -71.0575, 1, 'place-state', 'Built in 1713, the Old State House is Boston''s oldest surviving public building and was the seat of colonial government. The Boston Massacre took place outside it in 1770, and the Declaration of Independence was first read to Bostonians from its east balcony on July 18, 1776.'),
  ('faneuil-hall', 'landmark', 'Faneuil Hall', array['faneuil hall', 'faneuil', 'fanueil hall', 'cradle of liberty', 'faneuil hall marketplace']::text[], 42.36, -71.0562, 1, 'place-state', 'A gift to the town from merchant Peter Faneuil, Faneuil Hall opened in 1742 as a market and meeting hall. Speeches by Samuel Adams and others urging independence earned it the name "the Cradle of Liberty". Its grasshopper weathervane dates to 1742.'),
  ('paul-revere-house', 'landmark', 'Paul Revere House', array['paul revere house', 'revere house', 'paul reveres house', 'paul revere s house']::text[], 42.3637, -71.0537, 3, 'place-haecl', 'Built around 1680, this is the oldest surviving house in downtown Boston. Paul Revere owned it from 1770 to 1800 and left from here on his midnight ride of April 18, 1775. It has operated as a museum since 1908.'),
  ('old-north-church', 'landmark', 'Old North Church', array['old north church', 'old north', 'christ church in the city of boston', 'christ church boston']::text[], 42.3663, -71.0544, 1, 'place-haecl', 'Built in 1723, Old North is Boston''s oldest standing church building. On the night of April 18, 1775, two lanterns hung in its steeple signalled that British troops were crossing the Charles by water: "one if by land, two if by sea".'),
  ('uss-constitution', 'landmark', 'USS Constitution', array['uss constitution', 'old ironsides', 'constitution', 'the constitution ship', 'u s s constitution']::text[], 42.3724, -71.0566, 1, 'place-north', 'Launched in Boston in 1797, USS Constitution is the world''s oldest commissioned warship still afloat. She earned the nickname "Old Ironsides" in the War of 1812 when British cannonballs appeared to bounce off her oak hull.'),
  ('bunker-hill', 'landmark', 'Bunker Hill Monument', array['bunker hill monument', 'bunker hill', 'bunker hill memorial', 'the bunker hill obelisk']::text[], 42.3764, -71.0608, 1, 'place-ccmnl', 'This 221-foot granite obelisk, completed in 1843, commemorates the Battle of Bunker Hill of June 17, 1775, the first major battle of the Revolutionary War. It actually stands on Breed''s Hill, where most of the fighting took place.'),
  ('bpl', 'landmark', 'Boston Public Library', array['boston public library', 'bpl', 'mckim building', 'central library', 'boston public library mckim building', 'copley library']::text[], 42.3493, -71.0782, 2, 'place-coecl', 'The Boston Public Library was the first large free municipal library in the United States. Its McKim Building on Copley Square, designed by Charles Follen McKim and opened in 1895, was conceived as a "palace for the people" and carries the inscription "Free to All".'),
  ('trinity-church', 'landmark', 'Trinity Church', array['trinity church', 'trinity church boston', 'trinity church copley', 'trinity']::text[], 42.35, -71.0755, 2, 'place-coecl', 'Designed by Henry Hobson Richardson and consecrated in 1877, Trinity Church defined the style now called Richardsonian Romanesque. It rests on thousands of wooden piles driven into Back Bay''s filled land and is famously reflected in the glass of the neighbouring Hancock tower.'),
  ('public-garden', 'landmark', 'Boston Public Garden', array['public garden', 'boston public garden', 'the public garden', 'swan boats', 'boston public gardens']::text[], 42.3541, -71.07, 2, 'place-armnl', 'Established in 1837, the Public Garden was the first public botanical garden in the United States. Its Swan Boats have paddled the lagoon since 1877, and its small suspension footbridge and equestrian statue of George Washington are city icons.'),
  ('fenway-park', 'landmark', 'Fenway Park', array['fenway park', 'fenway', 'fenway stadium', 'red sox stadium', 'home of the red sox']::text[], 42.3467, -71.0972, 1, 'place-kencl', 'Open since 1912, Fenway Park is the oldest ballpark in Major League Baseball and home of the Boston Red Sox. Its 37-foot left-field wall, the Green Monster, and its hand-operated scoreboard are among the most recognisable features in sport.'),
  ('mit-dome', 'landmark', 'MIT Great Dome', array['mit great dome', 'great dome', 'mit dome', 'mit', 'killian court', 'mit building 10', 'massachusetts institute of technology']::text[], 42.3601, -71.0921, 2, 'place-knncl', 'The Great Dome crowns Building 10 at the heart of MIT''s Cambridge campus, designed by William Welles Bosworth and opened in 1916 when the Institute moved across the Charles from Boston. Modelled on the Pantheon, it overlooks Killian Court and is a favourite target of student "hacks".'),
  ('john-harvard', 'landmark', 'John Harvard Statue', array['john harvard statue', 'john harvard', 'statue of john harvard', 'statue of three lies', 'harvard statue', 'harvard yard statue']::text[], 42.3745, -71.1172, 2, 'place-harsq', 'Daniel Chester French''s 1884 bronze in Harvard Yard is nicknamed the "Statue of Three Lies": its inscription calls John Harvard the founder (he was a benefactor), dates the college to 1638 (it was 1636), and the face is a student model''s, since no likeness of Harvard survives. Visitors rub its left shoe for luck.'),
  ('longfellow-bridge', 'landmark', 'Longfellow Bridge', array['longfellow bridge', 'longfellow', 'salt and pepper bridge', 'salt and pepper shaker bridge', 'cambridge bridge']::text[], 42.3617, -71.0756, 2, 'place-chmnl', 'Opened in 1906 and later renamed for poet Henry Wadsworth Longfellow, this steel-arch bridge carries the Red Line and road traffic over the Charles River between Boston and Cambridge. Its four granite towers earned it the nickname "Salt-and-Pepper Bridge".'),
  ('zakim-bridge', 'landmark', 'Zakim Bridge', array['zakim bridge', 'zakim', 'leonard p zakim bunker hill memorial bridge', 'bunker hill bridge', 'zakim bunker hill bridge', 'leonard zakim bridge']::text[], 42.3688, -71.0631, 1, 'place-north', 'Completed in 2003 as the centrepiece of the Big Dig, the Leonard P. Zakim Bunker Hill Memorial Bridge carries Interstate 93 over the Charles River. Its two inverted-Y towers deliberately echo the Bunker Hill Monument nearby.'),
  ('custom-house', 'landmark', 'Custom House Tower', array['custom house tower', 'custom house', 'boston custom house', 'customs house tower', 'customs house']::text[], 42.3591, -71.0535, 2, 'place-aqucl', 'The Greek Revival Custom House was completed in 1847 at what was then the water''s edge. The 496-foot tower added in 1915 made it Boston''s tallest building for nearly half a century, exempt from city height limits because it was federal property.'),
  ('stn-park-street', 'station', 'Park Street', array['park street', 'park st', 'park street station', 'park']::text[], 42.3564, -71.0624, 1, 'place-pktrm', 'Park Street opened on September 1, 1897 as part of the Tremont Street Subway, the first subway in the United States. Today it is the transfer point between the Red and Green lines beneath Boston Common.'),
  ('stn-harvard', 'station', 'Harvard', array['harvard', 'harvard station', 'harvard square', 'harvard square station', 'harvard sq']::text[], 42.3734, -71.119, 1, 'place-harsq', 'Harvard opened in 1912 as the northern terminus of the Cambridge subway. The station was rebuilt in the 1980s when the Red Line was extended to Alewife, and its tunnel busway still carries buses beneath Harvard Square.'),
  ('stn-kendall', 'station', 'Kendall/MIT', array['kendall', 'kendall mit', 'kendall square', 'kendall station', 'kendall mit station', 'mit station']::text[], 42.3625, -71.0862, 2, 'place-knncl', 'Kendall/MIT has served the Red Line since 1912. Riders waiting on the platform can play the Kendall Band, an interactive musical sculpture by Paul Matisse hanging between the tracks.'),
  ('stn-charles', 'station', 'Charles/MGH', array['charles mgh', 'charles', 'charles street', 'charles mgh station', 'mgh', 'charles circle']::text[], 42.3612, -71.0706, 2, 'place-chmnl', 'Charles/MGH opened in 1932 as an elevated station above Charles Circle, where the Red Line emerges from Beacon Hill to cross the Longfellow Bridge. Its curved glass headhouse dates from a 2007 rebuild.'),
  ('stn-south-station', 'station', 'South Station', array['south station', 'south sta', 'boston south station']::text[], 42.3523, -71.0552, 1, 'place-sstat', 'South Station opened in 1899 and was once the busiest railway station in the world. Its curved neoclassical headhouse now anchors the Red Line, Silver Line, commuter rail and Amtrak''s Northeast Corridor.'),
  ('stn-government-center', 'station', 'Government Center', array['government center', 'govt center', 'government center station', 'scollay square', 'gov center']::text[], 42.3597, -71.0592, 2, 'place-gover', 'Opened in 1898 as Scollay Square, the station was renamed when the old square was cleared for City Hall Plaza in the 1960s. Its tall glass headhouse opened in 2016, and it links the Green and Blue lines.'),
  ('stn-kenmore', 'station', 'Kenmore', array['kenmore', 'kenmore square', 'kenmore station', 'kenmore sq']::text[], 42.3489, -71.0952, 2, 'place-kencl', 'Kenmore opened in 1932 beneath Kenmore Square, where the Green Line''s B, C and D branches split. It is the closest stop to Fenway Park, and its glass bus canopy sits below the famous Citgo sign.'),
  ('stn-alewife', 'station', 'Alewife', array['alewife', 'alewife station']::text[], 42.3958, -71.1413, 3, 'place-alfcl', 'Alewife opened in 1985 as the northern terminus of the Red Line''s Northwest Extension. Named for Alewife Brook and the herring that run in it, the station is topped by a large commuter parking garage.'),
  ('nbh-beacon-hill', 'neighborhood', 'Beacon Hill', array['beacon hill', 'beacon hill boston', 'acorn street']::text[], 42.3583, -71.0661, 1, 'place-chmnl', 'Beacon Hill is one of Boston''s oldest neighbourhoods, known for Federal-style brick rowhouses, gas-lit lanes and cobbled Acorn Street. The hill takes its name from a warning beacon that once stood at its summit.'),
  ('nbh-back-bay', 'neighborhood', 'Back Bay', array['back bay', 'back bay boston', 'newbury street', 'commonwealth avenue']::text[], 42.3503, -71.081, 2, 'place-coecl', 'Back Bay was a tidal mudflat until a massive landfill project begun in 1857 created the neighbourhood. Its orderly grid of Victorian brownstones, Newbury Street shops and the Commonwealth Avenue Mall is one of America''s best-preserved 19th-century districts.'),
  ('nbh-north-end', 'neighborhood', 'North End', array['north end', 'the north end', 'north end boston', 'little italy', 'hanover street']::text[], 42.3647, -71.0542, 2, 'place-haecl', 'Settled in the 1630s, the North End is Boston''s oldest residential neighbourhood. It has been the heart of the city''s Italian-American community for more than a century, famed for the bakeries and restaurants of Hanover Street.'),
  ('nbh-chinatown', 'neighborhood', 'Chinatown', array['chinatown', 'boston chinatown', 'china town', 'chinatown gate']::text[], 42.3513, -71.0607, 1, 'place-chncl', 'Boston''s Chinatown is the only surviving historic Chinese neighbourhood in New England. Its paifang gate on Beach Street, a gift from Taiwan installed in 1982, is guarded by a pair of foo lions.'),
  ('nbh-charlestown', 'neighborhood', 'Charlestown', array['charlestown', 'charlestown boston', 'charles town']::text[], 42.3753, -71.0644, 3, 'place-ccmnl', 'Founded in 1628, two years before Boston itself, Charlestown sits on a peninsula north of the Charles River. It is home to the Bunker Hill Monument and the Navy Yard, and was annexed by Boston in 1874.')
